import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner s = new Scanner(System.in);
        int n = s.nextInt();
        Map<String, Set<String>> versions = new TreeMap<>();
        for (int i = 0; i < n; i++) {
            String[] p = s.next().split(":", - 1);
            versions.computeIfAbsent(p[0] + ":" + p[1], k -> new TreeSet<>()).add(p[2]);
        }
        boolean ok = true;
        for (var e : versions.entrySet()) if (e.getValue().size() > 1) {
            System.out.println("CONFLICT " + e.getKey());
            ok = false;
        }
        if (ok) System.out.println("OK");
    }
}

