import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int n = s.nextInt();
        List<String> layers = List.of("unit", "integration", "e2e");
        Map<String, Integer> count = new LinkedHashMap<>(), time = new LinkedHashMap<>();
        for (String l : layers) {
            count.put(l, 0);
            time.put(l, 0);
        }
        for (int i = 0; i < n; i++) {
            String name = s.next(), layer = s.next();
            int ms = s.nextInt();
            count.merge(layer, 1, Integer::sum);
            time.merge(layer, ms, Integer::sum);
        }
        for (String l : layers) System.out.println(l + " " + count.get(l) + " " + time.get(l));
        System.out.println(count.get("unit") >= count.get("integration") && count.get("integration") >= count.get("e2e") ? "PYRAMID" : "INVERTED");
    }
}

